import {
  TrChatUI,
  useChatRuntimeAdapter,
  useChatRuntimeFromConversation,
  type ChatHistoryActionPayload,
} from '@opentiny/tiny-robot-chat'
import '@opentiny/tiny-robot-chat/dist/style.css'

